import{_ as s,a as i,c as e,ac as n}from"./chunks/framework.BSuaGltH.js";const g=JSON.parse('{"title":"pandas 转换机制：连接基数、分组与时区","description":"在销售数据中建立多对一连接、缺失分组、精确金额和可解释的月份边界。","frontmatter":{"title":"pandas 转换机制：连接基数、分组与时区","description":"在销售数据中建立多对一连接、缺失分组、精确金额和可解释的月份边界。","showdocs":{"topics":[{"id":"python","title":"Python","link":"/topics/python/"}],"kind":"知识专题","scope":"general","audience":"general","group":"语言与开发","seriesTitle":"pandas：销售质量、客户连接与月份报表","summary":"在销售数据中建立多对一连接、缺失分组、精确金额和可解释的月份边界。","status":"active","related":[{"title":"Django 入门：项目、路由与请求链","link":"/programming/python/django-request-model","kind":"开发实践","scope":"general","audience":"general"},{"title":"Django常见故障的定位顺序","link":"/programming/python/plus/troubleshooting/django-diagnostics","kind":"排错","scope":"general","audience":"general"},{"title":"Django个人任务板完整实践","link":"/programming/python/plus/practice/django-application","kind":"开发实践","scope":"general","audience":"general"},{"title":"Django个人任务板完整实践 · Django任务板完整工程包含哪些文件至全部工程文件与同源正文","link":"/programming/python/plus/practice/django-application-part-01","kind":"开发实践","scope":"general","audience":"general"},{"title":"Django个人任务板完整实践 · tasks/urls.py至版本与资料边界","link":"/programming/python/plus/practice/django-application-part-02","kind":"开发实践","scope":"general","audience":"general"}],"prev":{"text":"pandas 数据模型：列类型、索引与 CSV 契约","link":"/programming/python/plus/subjects/pandas-model"},"next":{"text":"pandas 完整实践：销售质量校验与客户月报","link":"/programming/python/plus/practice/pandas-application"}},"layout":"ReadingPage","sidebar":false,"aside":false,"prev":{"text":"pandas 数据模型：列类型、索引与 CSV 契约","link":"/programming/python/plus/subjects/pandas-model"},"next":{"text":"pandas 完整实践：销售质量校验与客户月报","link":"/programming/python/plus/practice/pandas-application"}},"headers":[],"relativePath":"programming/python/plus/subjects/pandas-transform.md","filePath":"programming/python/plus/subjects/pandas-transform.md"}'),t={name:"programming/python/plus/subjects/pandas-transform.md"};function p(r,a,l,h,o,d){return i(),e("div",null,[...a[0]||(a[0]=[n(`<h1 id="pandas-转换机制-连接基数、分组与时区" tabindex="-1">pandas 转换机制：连接基数、分组与时区 <a class="header-anchor" href="#pandas-转换机制-连接基数、分组与时区" aria-label="Permalink to &quot;pandas 转换机制：连接基数、分组与时区&quot;">​</a></h1><p>前置：<a href="/programming/python/plus/subjects/pandas-model#csv-schema">类型和CSV契约</a>。转换正确不只取决于API没有报错，还取决于行数、主键、总额和时间范围这些不变量。先验证事实表和维度表，再连接、聚合，最后排序输出。</p><h2 id="merge" tabindex="-1">连接基数与未匹配客户 <a class="header-anchor" href="#merge" aria-label="Permalink to &quot;连接基数与未匹配客户 {#merge}&quot;">​</a></h2><p>pandas合并后金额翻倍怎么查：先检查客户维度的键唯一性，再在merge指定validate=&#39;many_to_one&#39;约束多对一关系。销售允许多个订单属于同一客户，客户表同一个ID只能有一行；重复维度会展开笛卡尔组合，即使结果形状合法也会重复计算收入。不能靠合并后drop_duplicates掩盖上游歧义。</p><p>工程用left连接保留全部销售，并设置indicator=True，检查_merge全部为both；未知客户是数据错误，不能inner连接后悄悄丢单。pandas允许空连接键互相匹配，与常见SQL NULL语义不同，因此必须先拒绝空ID。连接前后可以检查销售行数和金额守恒，但守恒不是唯一性检查的替代品。 例如某键在事实表出现 2 次、在维度表出现 3 次时，无约束连接会产生 6 行。下游再求和已经无法知道其中哪一条维度记录才是正确归属。</p><div class="language-python vp-adaptive-theme"><button title="复制代码" class="copy"></button><span class="lang">python</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">joined </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> sales.merge(customers, </span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">on</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;customer_id&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">how</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;left&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">                     validate</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;many_to_one&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">indicator</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">True</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span></span></code></pre></div><p>这是局部片段，完整前置校验在<a href="/programming/python/plus/practice/pandas-application#source">report.py</a>。只需拼接同结构批次时用concat；join通常围绕索引，选择前先确认关联键，不要凭函数名字猜行为。<a href="https://pandas.pydata.org/pandas-docs/version/2.3.3/user_guide/merging.html" target="_blank" rel="noopener noreferrer">官方连接指南</a>用于核对连接验证和索引行为。</p><h2 id="groupby" tabindex="-1">缺失与分组计数 <a class="header-anchor" href="#groupby" aria-label="Permalink to &quot;缺失与分组计数 {#groupby}&quot;">​</a></h2><p>pandas分组为什么少了空地区：groupby的dropna会影响缺失键是否形成分组；本项目先将允许缺失的region填成unknown，再显式设置dropna=False。order_count使用size计算订单行数，count则统计指定列非缺失值，二者在有NA时可能不同。选择统计口径前先定义分母，不能把任一列的count都叫订单数。</p><p>as_index=False让分组键保持普通列，便于CSV输出；named aggregation为订单数和总分命名，避免多层列索引。sort=True使分组键排序，observed=True明确类别列只报告实际出现组合，减少未来默认变化影响。此处不是补齐所有月份×地区的网格，未发生交易的组合不输出；要展示零交易月份必须先定义日历维表再reindex，不能凭空推断缺行就是零。</p><div class="language-python vp-adaptive-theme"><button title="复制代码" class="copy"></button><span class="lang">python</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">summary </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> joined.groupby([</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;month&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;region&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">], </span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">as_index</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">False</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">                         dropna</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">False</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">sort</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">True</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">observed</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">True</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">).agg(</span></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">    order_count</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;sale_id&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;size&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">), </span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">total_cents</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;amount_cents&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;sum&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">))</span></span></code></pre></div><p>工程金额必填，所以sum不面对“全组未知金额”问题。其他数据中默认求和可能把全缺失表现为0，应考虑min_count并显式测试。详见<a href="https://pandas.pydata.org/pandas-docs/version/2.3.3/reference/api/pandas.DataFrame.groupby.html" target="_blank" rel="noopener noreferrer">groupby参数</a>。</p><h2 id="money" tabindex="-1">金额精度与溢出 <a class="header-anchor" href="#money" aria-label="Permalink to &quot;金额精度与溢出 {#money}&quot;">​</a></h2><p>pandas整数金额怎样避免溢出：金额采用整数分，先用Python任意精度int校验单行和全局总额，再转换int64用于分组；不能先在int64上求和再判断溢出。所有金额非负意味着任一分组总额不会超过全局总额，因而全局上界能保护每个分组。允许退款后这一证明不再成立，需要重新设计正负累计边界。</p><p>输入“1.25”不是125分，必须拒绝；负数、指数、NaN和前导零也不符合本项目格式。用float乘100再round会引入二进制表示和舍入规则，不是精确货币解析。若输入单位元，可以先用严格十进制文本解析或Decimal并定义舍入策略，然后转分。本项目刻意要求上游提供分，减少一次隐式业务变换。</p><p>行数上限10万、单笔上限10^12分使总额最多10^17，低于2^63−1；代码仍保留总额检查以便边界变化时显式失败。NumPy/pandas固定宽整数不具备Python int的自动扩展能力。 若把 10¹² 分的行上限放宽，却只在 <code>groupby().sum()</code> 后检查结果，固定宽度溢出可能已让分组值回绕，事后比较无法恢复原值。</p><h2 id="timezone" tabindex="-1">UTC存储与业务月份 <a class="header-anchor" href="#timezone" aria-label="Permalink to &quot;UTC存储与业务月份 {#timezone}&quot;">​</a></h2><p>pandas按上海月份统计怎么做：要求每个时间携带时区偏移，to_datetime先用utc=True统一瞬间，再tz_convert到Asia/Shanghai，最后strftime取当地月份。UTC的1月31日16点对应上海2月1日0点，先取UTC月份会把交易放错报表。tz_localize给无时区墙钟指定解释，tz_convert则转换已有时区瞬间，二者不能互换。</p><p>工程输入限定2025年完整秒ISO时间，解析器还负责检查真实日历；正则匹配不保证2月30日存在。当地业务窗口为[2025-01-01, 2026-01-01)，上界排除。原始文本年份2025不保证转换后的当地时间仍在2025，必须另验窗口。时区数据来自操作系统或tzdata；Windows准备环境时保留tzdata依赖。</p><p><a href="https://pandas.pydata.org/pandas-docs/version/2.3.3/reference/api/pandas.to_datetime.html" target="_blank" rel="noopener noreferrer">to_datetime</a>提供errors=&#39;raise&#39;和UTC转换参数。本工程拒绝无偏移时间，不猜夏令时重复时刻，不把coerce产生NaT后删除行当成成功清洗。</p><h2 id="copy" tabindex="-1">复制和赋值边界 <a class="header-anchor" href="#copy" aria-label="Permalink to &quot;复制和赋值边界 {#copy}&quot;">​</a></h2><p>pandas链式赋值为什么不可靠：避免frame[mask][&#39;x&#39;]=value，使用一次loc定位并赋值，或先copy后修改独立结果。pandas 2.3.3的Copy-on-Write是可配置行为，3.0采用CoW默认语义；本组不依赖切片写入原表的副作用，函数内只修改自己创建的数据对象。deep=True也不递归复制object列里嵌套的任意Python对象。</p><p>需要修改原表时用 <code>frame.loc[mask, &#39;x&#39;] = value</code>；需要新报表时用 <code>selected = frame.loc[mask].copy()</code> 并只修改selected。CoW主要改变共享底层数据时何时复制，不保证嵌套可变对象隔离，也不等于线程安全。参考<a href="https://pandas.pydata.org/pandas-docs/version/2.3.3/user_guide/copy_on_write.html" target="_blank" rel="noopener noreferrer">CoW版本说明</a>。</p><h2 id="exercise-transform" tabindex="-1">转换练习 <a class="header-anchor" href="#exercise-transform" aria-label="Permalink to &quot;转换练习 {#exercise-transform}&quot;">​</a></h2><p>客户001出现两行地区、另有一条客户999销售：分别预测many_to_one验证和_merge检查的作用。再给输入增加2025-12-31T16:00:00Z，判断它是否属于有效窗口。最后解释为什么有两个金额NA的分组不应自动宣称收入0。</p><details class="details custom-block"><summary>参考解法</summary><p>重复001在连接验证前已被客户唯一性检查拒绝；只保留唯一001后，999仍因未匹配失败。该时间转上海为2026-01-01T00:00:00+08:00，属于排除上界。未知金额不等于没有收入，先定义数据质量规则，再决定拒绝或保留NA；不能直接套用项目的必填金额假设。</p></details>`,26)])])}const c=s(t,[["render",p]]);export{g as __pageData,c as default};
